    (v_aula_id, 1, $p$Lembrando que você é bispo e vigia sobre o rebanho, conduzindo soldados de Cristo contra principados e potestades, com que seriedade você tem assumido a vigilância exigida por esse encargo?$p$, 'reflexao', null),
